"$L20\",\"wfwundefined-0-mama\",{\"href\":\"/en/search/synonyms/?original=mama\",\"children\":[\"$\",\"em\",null,{\"children\":\"mama\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"of Mine\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-5\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-yaḥ\",{\"href\":\"/en/search/synonyms/?original=yaḥ\",\"children\":[\"$\",\"em\",null,{\"children\":\"yaḥ\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"anyone who\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-6\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-vetti\",{\"href\":\"/en/search/synonyms/?original=vetti\",\"children\":[\"$\",\"em\",null,{\"children\":\"vetti\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"knows\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-7\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-tattvataḥ\",{\"href\":\"/en/search/synonyms/?original=tattvataḥ\",\"children\":[\"$\",\"em\",null,{\"children\":\"tattvataḥ\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"factually\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-8\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-saḥ\",{\"href\":\"/en/search/synonyms/?original=saḥ\",\"children\":[\"$\",\"em\",null,{\"children\":\"saḥ\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"he\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-9\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-avikalpena\",{\"href\":\"/en/search/synonyms/?original=avikalpena\",\"children\":[\"$\",\"em\",null,{\"children\":\"avikalpena\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"without d